long sum_big(const int *a, long n) {
    long s = 0;
    for (long i = 0; i < n; i++)
        if (a[i] >= 128)      // random data: taken about half the time
            s += a[i];
    return s;
}

int select(int c, int a, int b) {  // c is 0 or 1
    int mask = -c;   // 1 gives all ones, 0 gives 0
    int keep_a = a & mask;
    int keep_b = b & ~mask;
    return keep_a | keep_b;
}

